for folder,idx in [('values',0),('values-ar',1)]:
 out=['<resources>']
 for key,pair in strings.items():
  value=escape(pair[idx]).replace("'","\\'").replace('"','\\"').replace('\n','\\n')
  out.append(f'    <string name="{key}">{value}</string>')
 out.append('</resources>')
 (root/folder/'strings.xml').write_text('\n'.join(out)+'\n')
print(f'{len(strings)} localized strings written')
